-- ============================================
-- LUMA — Thème 9 : MOYEN 3/3 x4 — Gérer l'inventaire et un dilemme moral
-- ============================================


update scenarios set content = '{"characters": {"thorne": "Thorne", "gamemaster": "le maître du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "thorne", "text": "We only have one healing potion left, and both of us are badly wounded. What do we do?", "text_fr": "On n''a plus qu''une potion de soin, et on est tous les deux gravement blessés. Qu''est-ce qu''on fait ?", "choices": [{"text": "You should take it, Thorne. Your wounds look worse than mine.", "text_fr": "Tu devrais la prendre, Thorne. Tes blessures semblent pires que les miennes.", "next": "n2"}, {"text": "Let''s split it — half might help us both enough to continue.", "text_fr": "Partageons-la — la moitié pourrait nous aider assez tous les deux pour continuer.", "next": "n2b"}]}, "n1b": {"speaker": "thorne", "text": "(Grimaces in pain) I won''t lie, I''m not sure I can keep fighting like this.", "text_fr": "(Grimace de douleur) Je vais pas mentir, je suis pas sûr de pouvoir continuer à combattre comme ça.", "choices": [{"text": "Then it''s clear — you need this potion more than I do.", "text_fr": "Alors c''est clair — tu as besoin de cette potion plus que moi.", "next": "n2"}]}, "n2": {"speaker": "thorne", "text": "(Hesitates) Are you certain? We still have the boss chamber ahead of us.", "text_fr": "(Hésite) T''es sûr ? On a encore la chambre du boss devant nous.", "choices": [{"text": "I''m certain. I can manage with what I have — you need to be at full strength.", "text_fr": "Je suis sûr. Je peux gérer avec ce que j''ai — t''as besoin d''être au maximum.", "next": "n3"}, {"text": "(Reconsider) Actually, maybe we should think about this differently.", "text_fr": "(Reconsidère) En fait, peut-être qu''on devrait y penser différemment.", "next": "n3b"}]}, "n2b": {"speaker": "thorne", "text": "Splitting it means neither of us fully heals. That''s risky before the boss fight.", "text_fr": "Partager signifie qu''aucun de nous ne guérit complètement. C''est risqué avant le combat du boss.", "choices": [{"text": "You''re right, but going in with both of us slightly stronger feels safer than one being weak.", "text_fr": "T''as raison, mais y aller avec nous deux légèrement plus forts semble plus sûr qu''un de nous étant faible.", "next": "n3"}, {"text": "Good point. Let''s reconsider — maybe you should take the full potion after all.", "text_fr": "Bon point. Reconsidérons — peut-être que tu devrais prendre la potion entière après tout.", "next": "n3b"}]}, "n3": {"speaker": "thorne", "text": "(Nods slowly) Alright. I trust your judgment on this.", "text_fr": "(Hoche lentement la tête) D''accord. Je fais confiance à ton jugement là-dessus.", "choices": [{"text": "We''ll get through this together, one way or another.", "text_fr": "On va s''en sortir ensemble, d''une façon ou d''une autre.", "next": "n4"}]}, "n3b": {"speaker": "thorne", "text": "(Relieved) Thank you. I promise I''ll watch your back extra carefully in there.", "text_fr": "(Soulagé) Merci. Je promets de bien veiller sur toi là-dedans.", "choices": [{"text": "I know you will. Let''s face whatever comes next as a team.", "text_fr": "Je le sais. Affrontons ce qui vient ensuite en équipe.", "next": "n4"}]}, "n4": {"speaker": "gamemaster", "text": "(The healing potion is used according to your decision, and your party presses onward.)", "text_fr": "(La potion de soin est utilisée selon votre décision, et votre groupe avance.)", "choices": [{"text": "(Approach the boss chamber doors, weapons ready.)", "text_fr": "(Approche-toi des portes de la chambre du boss, armes prêtes.)", "next": "n5"}]}, "n5": {"speaker": "thorne", "text": "This is it. Whatever happens in there, I''m glad I have you watching my back.", "text_fr": "C''est le moment. Quoi qu''il arrive là-dedans, je suis content de t''avoir pour veiller sur moi.", "choices": [{"text": "Same here, Thorne. Let''s finish this together.", "text_fr": "Pareil pour moi, Thorne. Terminons ça ensemble.", "next": "n6"}]}, "n6": {"speaker": "gamemaster", "text": "(The doors creak open, revealing what lies beyond — the true test awaits.)", "text_fr": "(Les portes grincent en s''ouvrant, révélant ce qui se trouve au-delà — la vraie épreuve attend.)", "choices": [{"text": "(Step forward, ready to face whatever comes.)", "text_fr": "(Avance, prêt à affronter ce qui vient.)", "next": "end_bonded"}]}, "end_bonded": {"speaker": "thorne", "text": "Whatever we chose back there, it brought us closer as a team. Let''s go.", "text_fr": "Quoi qu''on ait choisi là-bas, ça nous a rapprochés en tant qu''équipe. Allons-y.", "end": true, "ending_label": "Dilemme résolu, lien d''équipe renforcé 💊🤝"}}}'::jsonb, is_playable = true
where title = 'Gérer l''''inventaire et un dilemme moral'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
